: ?><input type="checkbox" name="child_ids[]" value="<?= (int)$row['child_id'] ?>" aria-label="Select <?= esc($row['first_name'].' '.$row['last_name']) ?> for a reminder"><?php else: ?>—<?php endif ?></td><td class="p-3"><a class="font-semibold text-accent" href="<?= site_url('children/'.$row['child_id']) ?>"><?= esc($row['first_name'].' '.$row['last_name']) ?></a><span class="block text-xs text-gray-500"><?= esc($row['child_code']??'') ?></span></td><td class="p-3"><?= esc(age_label($row['birthdate'],null,true)) ?></td><td class="p-3"><?= esc($row['vaccine_name'].' · '.$row['dose_code']) ?></td><td class="p-3 <?= $row['display_status']==='Overdue'?'font-semibold text-red-700':'' ?>"><?= esc(format_date($row['due_date'])) ?></td><td class="p-3"><?= view('components/badge',['label'=>$row['display_status'],'tone'=>$row['display_status']==='Completed'?'success':($row['display_status']==='Overdue'?'danger':'warning')]) ?></td><td class="p-3"><?= esc($row['next_schedule']) ?></td><td class="p-3"><a class="text-accent" href="<?= site_url('children/'.$row['child_id'].'/immunizations') ?>">View</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td class="p-6 text-center text-gray-500" colspan="8">No scheduled vaccine doses match these filters.</td></tr><?php endif ?></tbody></table></div></section></form><?php if($view!=='calendar'): ?><div class="mt-4"><?= $pager->links() ?></div><?php endif ?><?php endif ?>
